# -*- coding: utf-8 -*-
"""أدوات الاستيراد من الصين إلى السعودية (8)."""
from biz_tools import F, S, add, CATS, T
DISC = 'الأرقام والنسب الجمركية تقديرية وتتغير؛ تحقق من الفسح الجمركي والمتطلبات الفنية للمنتج عبر الجهات الرسمية (هيئة الزكاة والضريبة والجمارك، ساسو، سابر) قبل الشراء.'
add('china-landed-cost', 'import', '📦', 'حاسبة التكلفة الواصلة والربح الحقيقي للمنتج المستورد',
    'من سعر المصنع باليوان إلى ربحك الفعلي بالريال: وكيل الشراء والشحن والتأمين والجمارك وضريبة القيمة المضافة والتخليص والتوصيل ورسوم المنصة والمرتجعات، مع هامش وعائد رأس المال وROAS التعادل.',
    [F('p', 'سعر الوحدة من المورد (يوان)', 'n', 12), F('q', 'الكمية', 'n', 300), F('fx', 'سعر الريال مقابل اليوان', 'n', 0.52), F('ag', 'عمولة وكيل الشراء %', 'n', 3),
     F('cn', 'الشحن داخل الصين (يوان إجمالي)', 'n', 150), F('fr', 'الشحن الدولي (ريال إجمالي)', 'n', 1800), F('ins', 'التأمين % من البضاعة', 'n', 0.5),
     F('du', 'الرسوم الجمركية %', 'n', 5), F('vt', 'ضريبة القيمة المضافة %', 'n', 15), F('cl', 'التخليص والمناولة (ريال إجمالي)', 'n', 300),
     F('dl', 'توصيل للعميل لكل وحدة', 'n', 12), F('sp', 'سعر البيع للعميل (شامل الضريبة إن كنت مسجلًا)', 'n', 69), F('mf', 'رسوم المنصة والدفع %', 'n', 3),
     F('rt', 'نسبة المرتجعات %', 'n', 5), F('ad', 'تكلفة الإعلان لكل وحدة', 'n', 10),
     S('rg', 'هل أنت مسجّل في ضريبة القيمة المضافة؟', [('y', 'نعم (أسترد ضريبة الاستيراد)'), ('n', 'لا (الضريبة تكلفة عليّ)')])],
    r'''function compute(v){const q=Math.max(1,v.q),g=v.p*q*v.fx,agt=g*v.ag/100,cn=v.cn*v.fx,fob=g+agt+cn,ins=fob*v.ins/100,cif=fob+v.fr+ins,du=cif*v.du/100,vat=(cif+du)*v.vt/100,isr=v.rg==='y';
const landed=cif+du+v.cl+(isr?0:vat),lu=landed/q,net=isr?v.sp/(1+v.vt/100):v.sp,fee=net*v.mf/100,ret=v.rt/100*lu,pbA=net-lu-v.dl-fee-ret,pf=pbA-v.ad,cap=landed+(isr?vat:0);
const rows=[['البضاعة (يوان→ريال)',f(g,0)],['عمولة الوكيل',f(agt,0)],['الشحن داخل الصين',f(cn,0)],['الشحن الدولي',f(v.fr,0)],['التأمين',f(ins,0)],['<b>قيمة CIF</b>','<b>'+f(cif,0)+'</b>'],['الرسوم الجمركية',f(du,0)],['ضريبة الاستيراد'+(isr?' (قابلة للاسترداد)':' (تكلفة)'),f(vat,0)],['التخليص',f(v.cl,0)],['<b>التكلفة الواصلة الإجمالية</b>','<b>'+f(landed,0)+'</b>']];
return kpis([kpi('التكلفة الواصلة للوحدة',f(lu,2)),kpi('صافي سعر البيع',f(net,2)),kpi('ربح الوحدة قبل الإعلان',f(pbA,2),pbA>0?'good':'bad'),kpi('ربح الوحدة بعد الإعلان',f(pf,2),pf>0?'good':'bad'),kpi('الهامش بعد الإعلان',f(net?pf/net*100:0,1)+'%',pf>0?'good':'bad')])
+'<h4>تفصيل الدفعة</h4>'+tbl(['البند','ريال'],rows)
+kpis([kpi('رأس المال المطلوب',f(cap,0)),kpi('ربح الدفعة كاملة',f(pf*q,0),pf>0?'good':'bad'),kpi('العائد على رأس المال',f(cap?pf*q/cap*100:0,0)+'%'),kpi('ROAS التعادل',pbA>0?f(net/pbA,2)+'x':'—'),kpi('كم وحدة لاسترداد رأس المال',pf>0?f(Math.ceil(cap/pf),0):'—')])
+rec([pf<=0?'المنتج يخسر بعد الإعلان: ارفع السعر، أو اخفض تكلفة الشحن بطلب أكبر أو شحن بحري، أو غيّر المنتج.':'هامش مقبول؛ اختبر بكمية صغيرة أولًا قبل الدفعة الكاملة.',pf>0&&pf/net<.2?'الهامش أقل من 20% — أي ارتفاع في الإعلان أو المرتجعات سيمحو الربح.':'',v.fr/q>lu*.25?'الشحن الدولي يستهلك أكثر من ربع التكلفة: قارن الشحن البحري أو زد الكمية.':'','لا تضع كل رأس المال في دفعة أولى؛ استخدم أداة «حجم أول طلب تجريبي».'])+note(''' + repr(DISC) + r''')}''')

add('sea-vs-air-freight', 'import', '✈️', 'مقارنة الشحن الجوي والبحري (التكلفة والزمن وكلفة تجميد المال)',
    'يحسب الوزن الحجمي والفعلي للشحن الجوي والحجم CBM للبحري، ثم يضيف كلفة تجميد رأس مالك أثناء الانتظار ليخبرك أيهما أرخص فعلًا لا ظاهريًا.',
    [F('u', 'عدد الوحدات', 'n', 1000), F('upc', 'وحدات في الكرتون', 'n', 20), F('l', 'طول الكرتون (سم)', 'n', 50), F('w', 'عرض الكرتون (سم)', 'n', 40), F('h', 'ارتفاع الكرتون (سم)', 'n', 35),
     F('kg', 'وزن الكرتون الفعلي (كجم)', 'n', 12), F('ar', 'سعر الشحن الجوي لكل كجم (ريال)', 'n', 28), F('sr', 'سعر الشحن البحري لكل CBM (ريال)', 'n', 420), F('mn', 'حد أدنى للشحن البحري (ريال)', 'n', 600),
     F('ad', 'أيام الشحن الجوي', 'n', 7), F('sd', 'أيام الشحن البحري', 'n', 35), F('gv', 'قيمة البضاعة (ريال)', 'n', 25000), F('cc', 'كلفة رأس المال السنوية %', 'n', 20), F('mu', 'ربح الوحدة المفقود لكل يوم تأخير (ريال/وحدة/يوم)', 'n', 0.1)],
    r'''function compute(v){const c=Math.ceil(v.u/Math.max(1,v.upc)),vol=v.l*v.w*v.h/6000,ch=Math.max(v.kg,vol),cbm=c*v.l*v.w*v.h/1e6,airC=c*ch*v.ar,seaC=Math.max(v.mn,cbm*v.sr);
const hold=d=>v.gv*v.cc/100*d/365,lost=d=>v.u*v.mu*d,airT=airC+hold(v.ad)+lost(v.ad),seaT=seaC+hold(v.sd)+lost(v.sd),best=airT<seaT?'air':'sea';
return kpis([kpi('عدد الكراتين',c),kpi('الوزن المحاسب للكرتون',f(ch,1)+' كجم'+(vol>v.kg?' (حجمي)':' (فعلي)')),kpi('الحجم الكلي',f(cbm,2)+' CBM'),kpi('الأوفر فعليًا',best==='air'?'الجوي ✈️':'البحري 🚢','good')])
+tbl(['','جوي','بحري'],[['تكلفة الشحن',f(airC,0),f(seaC,0)],['تكلفة تجميد رأس المال',f(hold(v.ad),0),f(hold(v.sd),0)],['ربح ضائع بسبب الانتظار',f(lost(v.ad),0),f(lost(v.sd),0)],['<b>الإجمالي الفعلي</b>','<b>'+f(airT,0)+'</b>','<b>'+f(seaT,0)+'</b>'],['الشحن لكل وحدة',f(airC/v.u,2),f(seaC/v.u,2)],['المدة',v.ad+' يوم',v.sd+' يوم']])
+rec([best==='sea'?'البحري أوفر حتى بعد احتساب كلفة الانتظار؛ خطّط المخزون مبكرًا.':'الجوي أوفر فعليًا لهذه الشحنة الصغيرة أو الثمينة أو السريعة الدوران.','فرق الشحن الظاهري '+f(airC-seaC,0)+' ريال، لكن الفرق الفعلي بعد الانتظار '+f(airT-seaT,0)+' ريال.',vol>v.kg?'الكرتون خفيف وكبير: الجوي يُحاسب بالحجم؛ قلّل حجم التعبئة (شفط الهواء/كرتون أصغر).':'الكرتون ثقيل مقارنة بحجمه: الجوي يُحاسب بالوزن.','اطلب عروضًا من مخلّصين مختلفين؛ الأسعار تتغير أسبوعيًا.'])}''')

add('container-cbm-planner', 'import', '🚛', 'مخطط الحاويات: كم كرتونًا تسع وهل LCL أم حاوية كاملة؟',
    'أدخل أبعاد الكرتون وعددها ليحسب CBM والوزن ونسبة امتلاء حاويات 20 و40 و40HQ، ويقارن تكلفة الشحن المجمّع LCL مع الحاوية الكاملة.',
    [F('c', 'عدد الكراتين', 'n', 400), F('l', 'الطول (سم)', 'n', 55), F('w', 'العرض (سم)', 'n', 40), F('h', 'الارتفاع (سم)', 'n', 40), F('kg', 'وزن الكرتون (كجم)', 'n', 14),
     F('lcl', 'سعر LCL لكل CBM (ريال)', 'n', 420), F('f20', 'سعر حاوية 20 قدم (ريال)', 'n', 6500), F('f40', 'سعر حاوية 40 قدم (ريال)', 'n', 9500), F('fhq', 'سعر حاوية 40HQ (ريال)', 'n', 10200),
     F('ef', 'كفاءة التحميل الفعلية %', 'n', 85)],
    r'''function compute(v){const cb=v.l*v.w*v.h/1e6,tc=cb*v.c,tw=v.kg*v.c,ef=v.ef/100;
const O=[['20 قدم',28,6500,v.f20,27000],['40 قدم',58,26500,v.f40,26500],['40HQ',68,26500,v.fhq,26500]].map(o=>{const cap=o[1]*ef/0.85,byV=Math.floor(cap/cb),byW=Math.floor(o[4]/v.kg),per=Math.min(byV,byW),n=Math.ceil(v.c/Math.max(1,per)),fill=v.c/(n*Math.max(1,per))*100;return{n:o[0],per:per,lim:byW<byV?'الوزن':'الحجم',cnt:n,cost:n*o[3],fill:fill}});
const lcl=tc*v.lcl,all=O.concat([{n:'LCL مجمّع',cost:lcl,cnt:'—',per:'—',lim:'—',fill:100}]).sort((a,b)=>a.cost-b.cost);
return kpis([kpi('حجم الكرتون',f(cb,3)+' CBM'),kpi('الحجم الإجمالي',f(tc,1)+' CBM'),kpi('الوزن الإجمالي',f(tw,0)+' كجم'),kpi('الأوفر',all[0].n,'good'),kpi('أقل تكلفة',f(all[0].cost,0))])
+tbl(['الخيار','كراتين/حاوية','القيد','عدد الحاويات','نسبة الامتلاء','التكلفة','لكل كرتون'],all.map(o=>[o.n,o.per,o.lim,o.cnt,o.cnt==='—'?'—':f(o.fill,0)+'%',f(o.cost,0),f(o.cost/v.c,1)]))
+rec([tc>=15?'حجمك '+f(tc,0)+' CBM — غالبًا الحاوية الكاملة تنافس LCL عند 15 CBM وأكثر.':'حجمك صغير؛ LCL أنسب لتجنب دفع مساحة فارغة.','القيد الأكثر تأثيرًا في بضاعتك: '+(v.kg>cb*300?'الوزن (بضاعة ثقيلة)':'الحجم (بضاعة خفيفة)')+'.','تفاوض على الرسوم المحلية (THC, DO) فهي لا تظهر في سعر الشحن الأساسي وقد تضيف 10–20%.'])+note('سعة الحاويات تقريبية؛ اطلب من المخلص خطة تحميل (loading plan) قبل الدفع.')}''')

add('supplier-quote-comparator', 'import', '🏭', 'مقارنة عروض الموردين بالتقييم الموزون',
    'ضع عروض الموردين من علي بابا أو 1688 أو المصنع لتصنفها بمعيار موزون: السعر والمدة والتقييم وملاءمة الحد الأدنى للكمية، وتعرف أيها أنسب فعلًا لا الأرخص فقط.',
    [F('d', 'العروض (مورد | سعر الوحدة يوان | الحد الأدنى MOQ | أيام الإنتاج | تكلفة العينة | الدفعة المقدمة % | تقييم 1-5)', 'textarea',
       'مصنع شنتشن | 11.5 | 500 | 20 | 40 | 30 | 4.5\nتاجر يوو | 10.2 | 200 | 12 | 25 | 100 | 3.2\nمصنع جوانجو | 12.8 | 300 | 15 | 0 | 30 | 4.8\nمورد علي بابا | 10.9 | 1000 | 25 | 60 | 50 | 4.0', r=6),
     F('q', 'كميتك المخطط شراؤها', 'n', 300), F('fx', 'سعر الريال مقابل اليوان', 'n', 0.52), F('wp', 'وزن السعر', 'n', 40), F('wl', 'وزن سرعة التوريد', 'n', 20), F('wr', 'وزن موثوقية المورد', 'n', 30), F('wm', 'وزن ملاءمة MOQ', 'n', 10)],
    r'''function compute(v){const R=lines(v.d).map(x=>({n:x[0],p:num(x[1]),m:num(x[2]),t:num(x[3]),s:num(x[4]),a:num(x[5])/100,r:num(x[6])})).filter(x=>x.n&&x.p>0);
if(R.length<2)return'<b>أدخل عرضين على الأقل.</b>';const wt=v.wp+v.wl+v.wr+v.wm||1,mp=Math.min(...R.map(x=>x.p)),mt=Math.min(...R.map(x=>x.t||1));
R.forEach(x=>{x.fit=x.m<=v.q?1:Math.max(0,v.q/x.m);x.q=Math.max(v.q,x.m);x.cost=(x.p*x.q)*v.fx+x.s*v.fx;x.dep=x.cost*x.a;x.sc=(v.wp*(mp/x.p)+v.wl*(mt/(x.t||mt))+v.wr*(x.r/5)+v.wm*x.fit)/wt*100});
R.sort((a,b)=>b.sc-a.sc);const b=R[0],ch=R.slice().sort((a,c)=>a.p-c.p)[0];
return kpis([kpi('الأنسب',b.n,'good'),kpi('درجته',f(b.sc,0)+'/100'),kpi('الأرخص سعرًا',ch.n),kpi('فرق السعر عن الأرخص',f((b.p/ch.p-1)*100,0)+'%')])
+tbl(['#','المورد','الدرجة','سعر (يوان)','MOQ','كمية الطلب','أيام','إجمالي (ريال)','دفعة مقدمة','موثوقية','ملاحظة'],R.map((x,i)=>[i+1,x.n,'<b>'+f(x.sc,0)+'</b>',f(x.p,2),f(x.m,0),f(x.q,0),f(x.t,0),f(x.cost,0),f(x.dep,0),f(x.r,1)+'/5',x.m>v.q?'⚠️ MOQ أعلى من كميتك':x.a>=1?'⚠️ دفع كامل مقدمًا':x.r<3.5?'⚠️ تقييم ضعيف':'✅']))
+rec(['اطلب عينة من أفضل مورّدين لا من الأرخص فقط؛ فرق 10% في السعر لا يعوّض مرتجعات 15%.','الدفع الكامل مقدمًا خطر: فضّل 30% مقدمًا والباقي قبل الشحن أو عبر Trade Assurance.','تفاوض على MOQ أقل مقابل سعر وحدة أعلى قليلًا عند أول طلب.','تحقق من المورد: ترخيص تجاري، صور مصنع، مراجعات مشترين سعوديين، ومكالمة فيديو.'])}''')

add('saudi-customs-duty-vat', 'import', '🛃', 'حاسبة الجمارك والضريبة للشحنة متعددة المنتجات',
    'وزّع الشحن والتأمين على أصناف الشحنة بنسبة قيمتها لتحصل على CIF لكل صنف، ثم يحسب الرسوم الجمركية وضريبة القيمة المضافة (على CIF + الرسوم) والإجمالي المستحق.',
    [F('d', 'الأصناف (صنف | قيمة FOB ريال | نسبة الجمارك %)', 'textarea', 'أغطية جوال | 4200 | 5\nسماعات | 7800 | 5\nأدوات مطبخ | 5500 | 5', r=5),
     F('fr', 'الشحن الدولي الإجمالي (ريال)', 'n', 2100), F('ins', 'التأمين الإجمالي (ريال)', 'n', 90), F('vt', 'ضريبة القيمة المضافة %', 'n', 15), F('fe', 'رسوم التخليص والمناولة (ريال)', 'n', 350)],
    r'''function compute(v){const R=lines(v.d).map(x=>({n:x[0],v:num(x[1]),d:num(x[2])})).filter(x=>x.n&&x.v>0);if(!R.length)return'<b>أدخل صنفًا واحدًا.</b>';const T=R.reduce((s,x)=>s+x.v,0);
R.forEach(x=>{const sh=x.v/T;x.cif=x.v+(v.fr+v.ins)*sh;x.du=x.cif*x.d/100;x.vat=(x.cif+x.du)*v.vt/100;x.tot=x.cif+x.du+x.vat});
const C=R.reduce((s,x)=>s+x.cif,0),D=R.reduce((s,x)=>s+x.du,0),V=R.reduce((s,x)=>s+x.vat,0),all=C+D+V+v.fe;
return kpis([kpi('إجمالي CIF',f(C,0)),kpi('الرسوم الجمركية',f(D,0),'bad'),kpi('ضريبة الاستيراد',f(V,0)),kpi('رسوم التخليص',f(v.fe,0)),kpi('المستحق عند الفسح',f(D+V+v.fe,0),'bad'),kpi('إجمالي التكلفة الواصلة',f(all,0))])
+tbl(['الصنف','FOB','CIF','جمارك %','الرسوم','الضريبة','الإجمالي'],R.map(x=>[x.n,f(x.v,0),f(x.cif,0),x.d+'%',f(x.du,0),f(x.vat,0),f(x.tot,0)]))
+rec(['الضريبة تُحسب على (CIF + الرسوم) لا على سعر المصنع فقط، لذا الشحن يرفع الضريبة أيضًا.','إن كنت مسجلًا في الضريبة تسترد ضريبة الاستيراد عبر إقرارك فلا تدخلها في تكلفة المنتج.','الشحنات الشخصية دون 1000 ريال معفاة من الرسوم (وعليها الضريبة)، أما الكميات التجارية فتتطلب سجلًا تجاريًا.','صنّف كل منتج ببند جمركي صحيح؛ الخطأ في البند يعني غرامة أو تأخير.'])+note(''' + repr(DISC) + r''')}''')

add('import-cash-cycle-planner', 'import', '⏳', 'مخطط الدورة النقدية للاستيراد (متى يخرج المال ومتى يعود)',
    'يرسم الخط الزمني من الدفعة المقدمة حتى استرداد رأس المال، ويحسب أقصى مبلغ تجمّده وموعد إعادة الطلب كي لا ينفد المخزون.',
    [F('tc', 'تكلفة الدفعة الواصلة (ريال)', 'n', 12000), F('dp', 'الدفعة المقدمة %', 'n', 30), F('pd', 'أيام الإنتاج', 'n', 20), F('sd', 'أيام الشحن', 'n', 35), F('cd', 'أيام الجمارك والتوصيل للمخزن', 'n', 7),
     F('u', 'عدد الوحدات', 'n', 400), F('np', 'صافي سعر البيع (ريال)', 'n', 60), F('ds', 'مبيعات يومية متوقعة (وحدة)', 'n', 6), F('sf', 'مخزون أمان (أيام مبيعات)', 'n', 10), F('ex', 'مصاريف تشغيل شهرية', 'n', 800)],
    r'''function compute(v){const lead=v.pd+v.sd+v.cd,dep=v.tc*v.dp/100,bal=v.tc-dep,rd=v.pd,arr=lead,sellDays=v.u/Math.max(.1,v.ds),rev=v.u*v.np,perDay=v.ds*v.np-v.ex/30;
const rcv=perDay>0?Math.ceil(v.tc/perDay):null,reo=Math.max(0,arr+sellDays-(v.pd+v.sd+v.cd)-v.sf),peak=v.tc;
const rows=[['اليوم 0','دفع المقدمة',f(dep,0)],['اليوم '+rd,'دفع الرصيد قبل الشحن',f(bal,0)],['اليوم '+arr,'وصول البضاعة للمخزن وبدء البيع','—'],[rcv?'اليوم '+(arr+rcv):'—','استرداد كامل رأس المال',rcv?'':'لا يتحقق'],['اليوم '+Math.round(arr+sellDays),'نفاد المخزون المتوقع','إيراد إجمالي '+f(rev,0)],['اليوم '+Math.round(reo),'موعد إعادة الطلب (لتصل قبل النفاد + أمان)','—']];
return kpis([kpi('أيام دورة التوريد',lead),kpi('أقصى مال مجمّد',f(peak,0),'bad'),kpi('أيام بيع الدفعة',f(sellDays,0)),kpi('استرداد رأس المال',rcv?(arr+rcv)+' يوم':'لا يتحقق',rcv?'good':'bad'),kpi('ربح الدفعة التقريبي',f(rev-v.tc-v.ex*sellDays/30,0))])
+tbl(['اليوم','الحدث','المبلغ'],rows)
+rec([lead>sellDays?'مدة التوريد أطول من مدة بيع الدفعة: ستنقطع عن البيع بين الدفعات؛ زد الكمية أو اطلب مبكرًا أو اعتمد مخزونًا احتياطيًا.':'مدة بيع الدفعة أطول من مدة التوريد: يمكنك الطلب التالي قبل نفاد المخزون بأمان.','أول '+f(arr,0)+' يومًا مالك مجمّد بلا إيراد؛ تأكد من سيولة تغطي التشغيل والإعلان خلالها.','قلّل التجميد بدفعات أصغر أو دفعة مقدمة أقل أو شحن أسرع للأصناف الرابحة.','اجعل نقطة إعادة الطلب = مبيعات يومية × (أيام التوريد + أمان).'])}''')

add('first-order-test-planner', 'import', '🧪', 'حجم أول طلب تجريبي: كم تشتري قبل أن تتأكد؟',
    'يقارن كميات اختبار مختلفة بثلاثة سيناريوهات للمبيعات ويحسب أقصى خسارة لكل خيار ليقترح أكبر كمية تبقى خسارتها ضمن حدّ تتحمله.',
    [F('b', 'ميزانية الاستيراد المتاحة', 'n', 10000), F('lu', 'التكلفة الواصلة للوحدة', 'n', 38), F('np', 'صافي سعر البيع', 'n', 79), F('sv', 'نسبة استرداد المخزون غير المباع % (تصفية)', 'n', 40),
     F('sp', 'نسبة البيع المتشائمة %', 'n', 10), F('sb', 'نسبة البيع المتوقعة %', 'n', 70), F('so', 'نسبة البيع المتفائلة %', 'n', 100), F('rk', 'أقصى خسارة تتحملها % من الميزانية', 'n', 15),
     F('o', 'كميات للمقارنة (مفصولة بفاصلة)', 't', '50, 100, 200, 300, 500')],
    r'''function compute(v){const Q=String(v.o).split(/[,،]/).map(num).filter(x=>x>0),sc=(q,p)=>{const sold=q*p/100,left=q-sold,rev=sold*v.np+left*v.np*v.sv/100;return rev-q*v.lu};
const R=Q.map(q=>({q:q,inv:q*v.lu,pe:sc(q,v.sp),ba:sc(q,v.sb),op:sc(q,v.so),ok:q*v.lu<=v.b&&-sc(q,v.sp)<=v.b*v.rk/100}));
const best=R.filter(x=>x.ok).sort((a,b)=>b.q-a.q)[0];
return kpis([kpi('أكبر كمية آمنة',best?f(best.q,0):'لا توجد',best?'good':'bad'),kpi('أقصى خسارة مسموحة',f(v.b*v.rk/100,0)),kpi('ربح الوحدة المتوقع',f(v.np-v.lu,2)),kpi('نسبة بيع التعادل',f(Math.max(0,(v.lu-v.np*v.sv/100)/(v.np*(1-v.sv/100))*100),0)+'%')])
+tbl(['الكمية','الاستثمار','% من الميزانية','متشائم','متوقع','متفائل','الحكم'],R.map(x=>[f(x.q,0),f(x.inv,0),f(x.inv/v.b*100,0)+'%','<span style="color:'+(x.pe<0?'#c33':'#0a7')+'">'+f(x.pe,0)+'</span>',f(x.ba,0),f(x.op,0),!x.ok?(x.inv>v.b?'❌ فوق الميزانية':'⚠️ خسارة محتملة أعلى من حدّك'):'✅ ضمن الحد']))
+rec([best?('ابدأ بحوالي '+f(best.q,0)+' وحدة: '+(best.pe<0?'أسوأ سيناريو يخسر '+f(-best.pe,0)+' ريال فقط.':'حتى في السيناريو المتشائم لا تخسر.')):'لا خيار ضمن حد الخسارة؛ ارفع هامش المنتج أو اخفض الكمية أو غيّر المنتج.','اختبر الطلب قبل الاستيراد: ملف قبل الطلب، إعلان على صورة المنتج، أو بيع مسبق لقائمة انتظار.','لا تدفع الحد الأدنى للكمية إن كانت أكبر من خيارك الآمن؛ اطلب عينات أو اشترِ من مورد جاهز بكمية صغيرة.','إن نجح الاختبار خلال 30 يومًا ضاعف الكمية تدريجيًا ولا تقفز مباشرة للكمية الكبيرة.'])}''')

add('product-sourcing-scorecard', 'import', '🎯', 'بطاقة تقييم المنتج قبل الاستيراد (طلب، منافسة، هامش، مخاطر)',
    'قيّم أكثر من منتج بثماني معايير من 1 إلى 5 لتحصل على درجة من 100 وتصنيف وإنذارات حمراء تمنعك من استيراد منتج خطر.',
    [F('d', 'المنتجات (منتج | طلب | قلة منافسة | هامش | صغر وخفة | سهولة نظامية | قلة مرتجعات | تميّز | تكرار شراء) كل معيار 1-5', 'textarea',
       'حامل جوال مغناطيسي | 5 | 2 | 3 | 5 | 5 | 4 | 2 | 2\nمنظم مكياج | 4 | 3 | 4 | 3 | 5 | 4 | 3 | 3\nشاحن لاسلكي | 5 | 2 | 3 | 4 | 3 | 3 | 2 | 2\nلعبة تعليمية | 4 | 4 | 4 | 3 | 2 | 4 | 4 | 3\nكاميرا مراقبة | 4 | 2 | 3 | 4 | 1 | 3 | 3 | 1', r=7)],
    r'''function compute(v){const W=[20,15,20,10,10,10,10,5],N=['طلب','منافسة','هامش','حجم','نظامي','مرتجعات','تميز','تكرار'];
const R=lines(v.d).map(x=>({n:x[0],s:x.slice(1,9).map(num)})).filter(x=>x.n&&x.s.length===8);if(!R.length)return'<b>أدخل منتجًا بثمانية تقييمات.</b>';
R.forEach(x=>{x.sc=x.s.reduce((a,s,i)=>a+Math.min(5,Math.max(1,s))/5*W[i],0);x.fl=[];if(x.s[4]<=2)x.fl.push('قد يحتاج شهادة/ترخيص (سابر)');if(x.s[2]<=2)x.fl.push('هامش ضعيف');if(x.s[0]<=2)x.fl.push('طلب ضعيف');if(x.s[1]<=1)x.fl.push('منافسة شرسة');if(x.s[5]<=2)x.fl.push('مرتجعات عالية');x.v=x.fl.length>=2||x.s[4]<=1?'🔴 لا تستورد قبل التحقق':x.sc>=75?'🟢 مرشح قوي — اطلب عينة':x.sc>=60?'🟡 يحتاج تحسين زاوية/سعر':'🟠 ضعيف'});
R.sort((a,b)=>b.sc-a.sc);
return kpis([kpi('الأفضل',R[0].n,'good'),kpi('درجته',f(R[0].sc,0)+'/100'),kpi('منتجات بإنذار أحمر',R.filter(x=>x.v.indexOf('🔴')===0).length,R.some(x=>x.v.indexOf('🔴')===0)?'bad':'good')])
+tbl(['#','المنتج','الدرجة'].concat(N).concat(['الحكم','إنذارات']),R.map((x,i)=>[i+1,x.n,'<b>'+f(x.sc,0)+'</b>'].concat(x.s).concat([x.v,x.fl.join('، ')||'—'])))
+rec(['الدرجة ليست قرار شراء؛ هي ترتيب أولوية للاختبار.','تحقق من الطلب بأدوات مثل Google Trends وعدد البائعين وأسعارهم على المنصات، ولا تعتمد على إحساسك.','أي منتج بدرجة «نظامي» منخفضة يحتاج مراجعة متطلبات سابر/المواصفات قبل أي دفع.','المنتجات الصغيرة الخفيفة ذات الهامش الجيد والمرتجعات القليلة أنسب للبداية.'])+note('الأوزان: طلب 20، منافسة 15، هامش 20، حجم 10، نظامي 10، مرتجعات 10، تميز 10، تكرار 5.')}''')
